import{_ as o,o as s,c as t,a2 as a}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse('{"title":"Rho status","description":"","frontmatter":{},"headers":[],"relativePath":"reference/status.md","filePath":"reference/status.md"}'),n={name:"reference/status.md"};function r(i,e,d,c,h,l){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="rho-status" tabindex="-1">Rho status <a class="header-anchor" href="#rho-status" aria-label="Permalink to &quot;Rho status&quot;">​</a></h1><p>Updated: 2026-11-11.</p><h2 id="current-focus" tabindex="-1">Current focus <a class="header-anchor" href="#current-focus" aria-label="Permalink to &quot;Current focus&quot;">​</a></h2><p><a href="/Rho/docs/records/figures-episode">Figures</a> (Figures 0.5.1, Notebook 0.5.13, Tables 0.5.2, in npm 0.5.7; scope frozen on 2026-11-08): a plot a Notebook cell draws is a figure whose marks are bound to the rows they came from: ggplot and what is built on it, base graphics such as <code>plotMA</code> and ComplexHeatmap in R, matplotlib and seaborn in Python. So is a file a cell saves with <code>ggsave()</code>, <code>png()</code>/<code>pdf()</code>/<code>svg()</code> and <code>dev.off()</code>, or <code>savefig()</code>, while the file keeps those bytes. The person selects marks in the cell, the Plots view, the answer board or the file view and asks; the Agent reads them with <code>figure.read</code> and points back with <code>figure.select</code>. Points drawn through <code>-log10</code>, <code>log2</code> and other transforms are bound through them, a column drawn on two scales in one plot is noted, and a figure binds up to 50,000 marks. Agents run their scripts in the session, so the files those scripts save stay figures (in trials, 0 of 6 runs ran one from a shell on the current guidance, 3 of 6 on the old, where 3 of 12 saved images became pictures), and a CSV with an unnamed row-name column previews. Records: <a href="/Rho/docs/records/saved-figures-episode">Saved</a>, <a href="/Rho/docs/records/drawn-figures-episode">Drawn</a>, <a href="/Rho/docs/records/python-figures-episode">Python</a>, <a href="/Rho/docs/records/figure-files-episode">Figure files</a>, <a href="/Rho/docs/records/script-runs-episode">Script runs</a>; <a href="/Rho/docs/records/semantic-figures-episode">Semantic figures</a> remains an optional two-view example. Checked by the Plugins describer checks on macOS, Linux and Windows in CI and by parallel Agent trials (<code>scripts/agent-trials.mjs</code>). Open, taken up only when a real run hits one: a file written outside the Notebook (a shell <code>Rscript</code>, a person&#39;s own program) stays a picture and does not say why; <code>imshow</code> heatmaps, multi-page PDFs, devices opened through package imports, ragg or svglite, and points plotted in another order than their table stay pictures or unbound; heatmap labels are unreadable at phone width; whether the scale note helps when the drawing cell does not show the transform is unknown. R figures did not draw in browsers that parse XML with libxml2 (Safari, and Electron 37 apps such as WorkBuddy), as the view gave the svg tag a second namespace; Plugins <code>888fe50</code> fixes it and Rho selects it since 2026-11-10, not yet in npm, and browser checks run Chromium 156, whose Rust parser hid it (<a href="/Rho/docs/records/figures-episode#iterations-and-causes">record</a>). No independent researcher has used figures (stage 3).</p><p><a href="/Rho/docs/records/plugin-markets-episode">Remote plugin markets</a>: people add, refresh and remove HTTPS indexes in Plugins or the CLI. Cached keywords find Semantic figures through <code>ggtree</code> and <code>clusterProfiler</code>; reads make no network requests. Failed refreshes retain the previous index, installs bind its digest and check the package identity/version, and removal keeps installed packages searchable. Fifteen focused checks, the contract check and the real Chrome/public Git episode passed at four widths. A second fresh service added the published YuLab HTTPS index through the CLI, found and installed Semantic figures in the browser, opened its view and refreshed the public source. In npm 0.5.7; the person&#39;s running instance was not restarted.</p><p><a href="/Rho/docs/records/plugin-pictures-episode">Plugin pictures</a>: each plugin on the Plugins page shows how it is reached (UI, Rho page, MCP tools, Skills, Claude Code, MCP server, CLI) from its declarations and the commands its package links. Cards and view rows show pictures of 11 real views captured from the PA14 example by <code>scripts/plugin-previews.mjs</code>, and Show it here mounts the actual view on a file of the open project. Third-party packages have a restyled section, a frame that follows its page and a designed <code>rho plugin create</code> page. The 27 focused checks, the contract check and three real Chrome checks passed. It follows <a href="/Rho/docs/records/plugin-disclosure-episode">plugin disclosure</a>, which made every view, Skill, operation and native entry searchable and readable. In npm 0.5.7 with Agent 0.4.33; the person&#39;s running instance was not changed.</p><p><a href="/Rho/docs/records/studio-context-episode">Studio context</a>: each Agent-panel message freezes its sending tab and Studio workspace; an empty layout can be deleted and restored through conditional composition operations. A real OpenCode/GLM run deleted Workspace 3, identified Workspace 2 on the next message, deleted a recreated version and restored the named layout. Project files stayed intact. In npm 0.5.7; the person&#39;s running instance was not changed.</p><p><a href="/Rho/docs/records/session-continuity-episode">Session continuity</a>: a Claude Code, Codex or Harness session in the project folder continues in Rho&#39;s Agent panel under its own session ID, wherever it started; sessions from outside Rho are no longer read-only. Conversations is one list read from each Agent&#39;s own records. A session open in another window is refused with where it is open, or continues as a copy. The Agents tab replaces new-conversation settings and holds the <a href="/Rho/docs/records/agent-connect-episode">connection prompt</a>. A real Claude Code passed all 8 steps (Rho and terminal in turn, held refusal, copy); Harness resumed both ways through <code>dsh acp</code>; Codex only with a test Agent. A real Codex (Westlake glm-5.3-flash) in Rho&#39;s panel refused every message after its first as <a href="/Rho/docs/records/session-continuity-episode#codex-in-rhos-own-panel">&quot;open in Codex&quot;</a>: the writer lock was Rho&#39;s own connection. It now counts as Rho&#39;s, and four messages in a row were answered (source, not yet released). With Codex 0.167 on PATH, that Westlake configuration fails every prompt. <a href="/Rho/docs/records/session-continuity-episode#npm-delivery">Rho 0.5.6</a>, with Agent 0.4.30 and the latest selected Core and Plugins sources, is npm <code>latest</code>. All 15 CI jobs passed; registry bytes match the tested candidate, and a fresh registry installation passed the CLI and composition checks. The <a href="https://yulab-smu.top/Rho/" target="_blank" rel="noreferrer">website</a> also names 0.5.6. <a href="/Rho/docs/records/opencode-episode">OpenCode</a>, never checked before, configured its own MCP connection, ran in Rho over ACP and continued one session between Rho and its terminal with no OpenCode code in Rho; Rho&#39;s source after 0.5.6 names an ACP Agent as it names itself. Its outside sessions are not yet listed, and turns from its other windows are not shown. The Agents tab is now <a href="/Rho/docs/records/agent-connect-episode#one-list-and-ready-entries">one list</a> for Agents Rho starts and Agents connected from their own windows, each with its mark from the new <a href="https://github.com/YuLab-SMU/Rho-plugins/blob/main/plugins/agent-icons/README.md" target="_blank" rel="noreferrer">Agent icons</a> plugin (62 Agents and makers), and the grant reply carries ready entries for Claude Code, Codex, OpenCode and Harness; OpenCode&#39;s setup took 90 s instead of 213 s. The setup prompt is now the request and <a href="/Rho/docs/records/agent-connect-episode#one-command">one command</a>, <code>rho connect</code>, whose reply tells the Agent the rest; OpenCode configured itself in 32 s and verified in a new session. Rho no longer starts only Claude Code, Codex and one ACP command fixed at start: the Agents tab <a href="/Rho/docs/records/agents-in-rho-episode">adds any ACP Agent</a>, found installed, typed, or connected from its own window (Use in Rho), and each conversation keeps the command it started with. Hermes 0.21.5 and Kimi Code 2.5.2 were added and answered in Rho&#39;s panel; Gemini CLI and an old Qwen were refused with their own reasons. Harness sessions continue only through Harness&#39;s own command. Checked on source with Agent 0.4.32 and shipped in npm 0.5.7; the person&#39;s running Rho was not restarted. A project opened after the example project listed the example&#39;s Codex sessions in its Studio and could read them: the Agent plugin kept each Codex file&#39;s summary without the project it was checked for. Plugins <code>b2c6197</code> keeps each session&#39;s own folder and compares it on every listing; <code>session-continuity</code> now opens a second project in the same service and fails on the previous Plugins. In Chrome, a project made after the example was shown listed the example&#39;s two Codex sessions under Studio with the previous Plugins and none with <code>b2c6197</code> (<a href="/Rho/docs/records/session-continuity-episode#another-projects-codex-sessions">episode</a>; prepared as 0.5.9).</p><p><a href="/Rho/docs/records/external-work-episode">External work views</a>: the original two-turn Harness mean-comparison session now appears in Conversations, Graph, Console, the answer board and a derived Studio with data, script, Notebook, table and figure. The fourteen native shell commands and two existing cells are observed without rerunning them; exact cell IDs join the timeline, reported links do not acquire historical bytes, and replay keeps unknown result times. A read failure and recovery were checked in the real browser. The existing service and R session keep running; after the isolated preview check, the checked WebUI assets are served from the original address as a local build override. dsh-rho 0.1.6 loaded in Desktop 0.2.2-rc.1 after 0.1.5 was refused for its declared version; its scoped bridge replaces the demo&#39;s tools-only entry. In npm 0.5.7. <a href="/Rho/docs/records/external-conversations-episode">Earlier external conversations</a> retain the 0.5.5/adapter 0.1.5 publication, original palette-change check and dependency audit scope.</p><p>The <a href="/Rho/docs/reference/third-party-plugins">third-party plugin channel</a> now installs independent packages; sclet and a generated package have real native/browser <a href="/Rho/docs/records/third-party-plugins-episode">evidence</a>. The application path is included in 0.5.5; external plugin packages retain their own delivery.</p><p><a href="/Rho/docs/records/dsh-rho-episode#conversation-project-matching">dsh-rho project matching</a> binds tools and the launcher to the same verified folder. The earlier public 0.1.5 Git package was checked in Desktop. The <a href="/Rho/docs/reference/deepseek-harness#plugin-settings-and-updates">0.1.7 source candidate</a> exports a <code>Config</code> schema for the connection files, command, arguments, bridge limit and reply wait and registers a <code>plugins.bundle.config</code> card, so Harness gives the bundle its own settings entry: 9 adapter checks, a fresh tarball install and a disposable Harness profile passed, but the rendered card is not yet observed in a running Desktop. Harness gives a new-version control only to a bundle installed from a registry spec, so the Git and tarball route keeps off/uninstall/install. A <code>dsh-rho-v*</code> tag runs <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/../.github/workflows/publish-dsh-rho.yml" target="_blank" rel="noreferrer"><code>publish-dsh-rho.yml</code></a>: npm <code>dsh-rho@0.1.7</code> was published by it with the repository <code>NPM_TOKEN</code> (npm trusts a workflow only for an existing package), with provenance; the registry bytes match the tested tarball, and fresh registry and disposable-profile installations by name pass (recorded as <code>^0.1.7</code>). Later versions publish through npm Trusted Publishing with no login or token; 0.1.8, the same files, validates it. The new-version control is not yet observed in Desktop. CI passed on <code>4f1e9c8d</code>. The checked <code>site/market/index.json</code> still selects 0.1.7 from the Git source; the site publication is a separate step. Result review and offline evidence retain their <a href="/Rho/docs/records/review-evidence-episode">episode</a>. Native tools remain normal; Core is optional. No Core execution behavior changed. <a href="/Rho/docs/records/p3-continuity-episode">P3 continuity</a> reproduced a 64-turn stop and continued it after reopening; the restarted Notebook&#39;s in-memory state did not survive, and four native choices remained. Claude sessions now prefer Auto, and Rho sets no step or wall cap by default. Rerun so, P3 asked for no permission; the Agent&#39;s MCP bridge had cut Notebook calls at 30 s and then 300 s, and without those cuts P3 finished in the shared R session in 12.9 minutes.</p><p>The <a href="https://github.com/YuLab-SMU/Rho-paper" target="_blank" rel="noreferrer">research method proposal</a> centers on purpose-driven composition: selecting materials, arranging related views and operations, and carrying their meaning into Agent continuation. Plugins supply information, compute and environment capabilities. The single-cell walkthrough distinguishes scientific purposes and how inputs and execution conditions change the workspace. Galaxy and JupyterLab constrain plugin-related novelty alongside interface and shared-context comparisons. Remote connections remain illustrative; novelty and human benefits are not established by existing Rho checks.</p><table tabindex="0"><thead><tr><th>Part</th><th>Current behavior</th><th>Evidence or remaining work</th></tr></thead><tbody><tr><td>Immutable capture</td><td>Files snapshots survive original overwrite/deletion; disk and dirty buffer versions differ; server-side new-turn collection has budgets/gaps</td><td>Owner and conversation fault tests; no retrospective reconstruction</td></tr><tr><td>Result review</td><td>Row/range/resource questions, explicit replies, multi-field keyed differences, code changes and human decisions</td><td>Real airquality and browser trials; new versions need a new decision</td></tr><tr><td>Agent feedback</td><td>Frozen contexts join message identities; direct sends are separate from deciding; external handoff copies</td><td>Real Claude and Codex trials; context fetch differs from explicit reply</td></tr><tr><td>Graph</td><td>Exact captured refs and capture times, current-file action separate, honest reported/named/observed links, bounded focus</td><td>Same-path versions and 160-node-cap regressions; old records show gaps</td></tr><tr><td>Offline evidence</td><td>Preview one review and explicit refs; static reader/original files/manifest; read-only verifier</td><td>Service closed/project moved; four browser widths; tamper detection</td></tr><tr><td>macOS 0.5.1</td><td>Unsigned npm tarball/local WebUI selected; Core bundled explicitly</td><td><a href="/Rho/docs/records/preview-0-5-1">Fixed tarball installed and exercised</a></td></tr><tr><td>0.5.2 candidate</td><td>16 MB tarball for macOS arm64 and Linux x64/arm64, and a 12 MB Windows x64 one: one Core per platform (Core <code>c3dbeca</code>), Claude Code/Codex the person&#39;s own, all 12 plugins</td><td><a href="/Rho/docs/records/package-0-5-2-episode">Packing, real Claude/Codex</a>; <a href="/Rho/docs/records/platforms-0-5-2-episode">offline install on four systems, Linux Notebook and Open folder</a>; <a href="/Rho/docs/records/windows-0-5-2-episode">Windows: Host lifetime and stop, installed checks</a>; x64 only under Rosetta; the full 0.5.1 acceptance not done</td></tr><tr><td>CI and npm</td><td>Each push that changes more than documentation builds the four Cores (each Core commit once), runs the suite and the selected Plugins&#39; figure describer checks on macOS, Linux and Windows, packs one candidate for all four platforms (3,030 files, 23 MB; bundled third-party packages keep what Node loads, licenses and reached declarations) and installs it offline on each; a <code>v*</code> tag publishes the candidate CI tested for that commit as <code>@rho-workspace/rho</code>, building nothing</td><td><a href="/Rho/docs/records/ci-episode">CI episode</a>: every job passes on the four platforms since run 7; <a href="/Rho/docs/records/ci-episode#publication"><code>@rho-workspace/rho@0.5.4</code></a> published on 2026-11-05 from the candidate CI run 41975339969 tested, with provenance and its README, declaring <code>&gt;=22.22.0 &lt;27</code>; npm served it 55 minutes after accepting it, byte-identical to that candidate, and Linux x64 also installs it on Node 24 and 26; CI failed from <code>e92efb12</code> until <code>826d73c1</code> selected the Plugins commit the Data flow imports; pruning cut the Windows offline install by 35–39%; on Windows a project Host can be unreachable right after its ready line (Core makes its first named pipe only in the accept thread, read in <code>8bed8ef</code>): one Test win32-x64 failure in <a href="/Rho/docs/records/outside-agent-episode#ci">CI 42736131288</a>, passing on rerun, is open work for Rho-core</td></tr><tr><td>Third-party plugins</td><td>Runtime package installation, checked snapshots, CLI development, directory and Plugins management; optional sclet adapter uses the shared R session</td><td><a href="/Rho/docs/records/third-party-plugins-episode">Episode</a>: real 200 × 60 synthetic SCE, PCA, audited report, stale-plan refusal and browser lifecycle. Source after 0.5.4; no npm release or independent usability claim</td></tr><tr><td>Independent researcher use</td><td>Unobserved</td><td>Trial guide in the episode; no usability claim</td></tr><tr><td>Example project</td><td><code>example/pa14-qs</code> ships with the application; a new state copies it into the projects folder once, as an ordinary editable project</td><td><a href="/Rho/docs/records/example-project-episode">Episode</a>. Without folders (after 0.5.3), <code>npx @rho-workspace/rho</code> starts on <code>~/Rho/projects</code> and <code>~/Rho/state</code>, ships this project, and names a missing Agent client or R at startup; flagged starts are unchanged. The full suite also passes on Node 18.20.8 (end of life), below the engine range&#39;s 22.22.</td></tr><tr><td>dsh-rho 0.1.4</td><td>Prebuilt public Git package and Rho’s own market index; each conversation’s tools and launcher select the same verified folder; <a href="/Rho/docs/reference/deepseek-harness">installation and upgrade guide</a></td><td><a href="/Rho/docs/records/dsh-rho-episode#public-workspace-fix">Public workspace fix</a>: two fresh Harness 0.2.1-rc.5 installs, with and without scripts; all nine files match; direct public-index search, recovery after an unmatched query and the selected source detail checked; 6/6 adapter tests and earlier real MCP/Desktop project checks. No npm, default-source, TUI or other OS claim</td></tr><tr><td>Literature reproduction</td><td>Five papers of the 97 fully-open corpus reproduced in Rho 0.5.2 (bulk, snRNA-seq, GeoMx DSP, bulk+metabolome, multi-omics): Agents ran R in the shared Notebook, Rho captured cells, values, figures and notes</td><td><a href="/Rho/docs/records/literature-repro-episode">Episode</a>: two of five needed one turn and three needed 2–4, because the Agent client capped at 64 turns or waited on an event nothing wakes; 8–24 approval choices per run (counted); resource paths guessed. Conversation return and turn-limit continuation have a later <a href="/Rho/docs/records/p3-continuity-episode">P3 pass</a>; the other issues remain.</td></tr><tr><td>Agent practice Skill</td><td><code>rho.analysis-run</code> 1.2 is a shipped Skill for running a whole analysis in the live sessions, and every conversation started here is told to read it before a multi-step analysis</td><td>Written from the five reproductions above: spend calls on the analysis not on re-discovery, never wait for an event that does not come, draw to an explicit device, write files complete and to disk, run scripts in the session, and report the state actually reached. Read back through <code>skill.list</code>/<code>skill.read</code> on a running service; <code>test:notebook</code> is its verify command</td></tr><tr><td>Agent setup</td><td>A person asks their Agent to read <a href="https://yulab-smu.top/Rho/doc/setup.md" target="_blank" rel="noreferrer">https://yulab-smu.top/Rho/doc/setup.md</a> (<a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/../SETUP.md" target="_blank" rel="noreferrer">SETUP.md</a>); the Agent checks Node, npm and npm&#39;s command folder, installs the npm package, starts Rho on <code>~/Rho/projects</code> and <code>~/Rho/state</code> with <code>--background</code>, checks it with <code>rho --status</code>, installs the Agent Skill the package ships with <code>rho --install-skill</code> and connects itself to the example project, with plain commands on every system (<code>rho.cmd</code> on Windows, no script); <code>rho --stop</code> stops Rho in order from any program</td><td><a href="/Rho/docs/records/docs-site-episode#setup-page-and-agent-skill">Episode</a> and <a href="/Rho/docs/records/windows-setup-episode">Windows</a> (#112, #113) for the 0.5.3–0.5.7 page. <a href="/Rho/docs/records/install-feedback-episode">Setup reports</a> (#114, #115, and Huorong flagging the PowerShell file the page had Agents write as a downloader): the new page followed on macOS in a throwaway home, where a new Claude Code session reached the granted project and <code>rho connect</code>&#39;s doubled state folder was fixed; source only, so the site keeps the 0.5.7 page until the next npm release; Huorong, Codex Desktop and Windows by hand unobserved</td></tr><tr><td>Outside Agents</td><td><code>rho open [FOLDER]</code> starts Rho when needed, opens the folder as a project where it is (outside the projects folder, the person&#39;s tab alone, through the operator credential&#39;s full-path <code>project.open</code>) and its page in the browser, and says what to tell the person; `rho tool index</td><td>resolve</td></tr><tr><td>WorkBuddy connector</td><td><a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/../adapters/workbuddy-rho/README.md" target="_blank" rel="noreferrer">adapters/workbuddy-rho</a> builds a CLI connector, <code>rho-workspace</code>, for WorkBuddy&#39;s open platform: <code>npm install -g @rho-workspace/rho</code> with a Node WorkBuddy provides, <code>rho --version</code> (0.5.8 or later) as its status, and a Skill for <code>rho open</code> and <code>rho tool</code>; Rho&#39;s connect reference tells an Agent in WorkBuddy to leave <code>mcp.json</code> alone</td><td><a href="/Rho/docs/records/workbuddy-connector-episode">Episode</a>: WorkBuddy had written three Rho MCP servers it never ran (they wait for the person&#39;s approval) and made an expert only when named. With WorkBuddy&#39;s own agent core and GLM-5.3-flash, opening the folder took 25–26 s with the Skill (34–35 s without) and every run said Rho is a browser page with its address; the volcano plot was drawn as a Notebook cell through <code>rho tool</code> in 3 of 3 runs with the Skill (94–168 s, address in 3) and 2 of 3 without. Not submitted; needs Rho 0.5.8 on npm; the desktop app and its model unobserved</td></tr><tr><td>Documentation site</td><td><a href="https://yulab-smu.top/Rho/" target="_blank" rel="noreferrer">https://yulab-smu.top/Rho/</a> is a front page with the real WebUI replaying the shipped PA14 project&#39;s recorded session (no backend), the one install sentence that sends an Agent to the setup page, and the recorded and per-plugin example prompts, with no desktop installers until a current desktop release; <code>docs/</code> is published under <code>/docs/</code> with local search and every page naming its source file</td><td><a href="/Rho/docs/records/docs-site-episode">Episode</a>: the demo tour gets every request answered at 1440 and 390 px; the install prompts&#39; commands ran on npm 0.5.3, and the front page now gives <a href="/Rho/docs/records/docs-site-episode#the-front-page-asks-for-the-sentence">the sentence</a> instead; <a href="/Rho/docs/records/docs-site-episode#the-install-prompt-on-a-real-machine">one Codex run</a> stopped at the Node check, lost its background start and exposed a port that moved per start, Codex grants shown as Claude Code&#39;s and stack-trace refusals, fixed in Rho; the prompts are unchanged; the four <code>updates/*.json</code> feeds are unchanged; the front page and documentation home now <a href="/Rho/docs/records/docs-site-episode#the-release-npm-serves-read-when-the-page-opens">read the npm version</a> when they open, so a release needs no deployment for it; the documentation, setup page and Skill were redeployed with <a href="/Rho/docs/reference/release#ci-and-npm-publication">0.5.7</a> from <code>3ba229d8</code>; the demo is still the earlier build, as the current WebUI asks for <code>agent.sessions.list</code> and <code>figure.read</code>, which its recording does not answer; no outside reader yet</td></tr><tr><td>Python environments</td><td>An Agent makes an environment in the project and passes <code>interpreter</code> (<code>.venv/bin/python</code>) to <code>kernel.run</code> (Notebook 0.5.3); the project keeps it for that language, a session only the Agent used starts again with it, and each session and cell records its program and version; the Agent panel reads install commands as what they installed</td><td><a href="/Rho/docs/records/python-env-episode">Episode</a>: five real runs outside Rho and from its Agent panel; installs made inside cells are not read as installs; other models and Codex unobserved</td></tr><tr><td>Variable relations</td><td>Under each Notebook cell, what it read and from which cell, and the later cells that read what it made; Variables names the cell that made each value and those that read it; Data flow is a graph of values from the files read to the results written or plotted, each node titled with the meaning the code&#39;s <code># means:</code> comment gives (the Agent writes these; read from the text, never run), with functions and constants named on what uses them, a bar to trace one result, and the chosen value&#39;s path and details; beside a script&#39;s editor it is read from the text (R and Python) and marks the lines behind and in front of the chosen value (Notebook 0.5.5, Documents 0.4.11)</td><td><a href="/Rho/docs/records/variable-flow-episode#redesign-a-graph-of-values">Episode</a> and <a href="/Rho/docs/records/variable-flow-episode#meaning-in-the-code">meanings</a>: redesigned after the user judged the boxes useless; the shipped example in a real browser at 1440, 1920 and 390 px; with comments written by hand, the editor shows 13 of 19 values with a meaning, and a fresh Agent run&#39;s script reads as 6 of 7 values and both written files; read, not run, so names built at run time, dplyr columns named like a value and pasted paths are missed; the meanings are the Agent&#39;s words and no person has used them</td></tr></tbody></table><p>M0 retains Python/R highlighting, Markdown reading and native command exit/time/bounded output (<a href="/Rho/docs/records/code-markdown-episode">record</a>); its report trial keeps scripts, results and report after originals change. A first Codex feedback attempt cancelled by the acceptance&#39;s permission selector stays recorded beside the corrected trial; Annotations 0.5.1 keeps a new Review conversation for later feedback. Installed Codex needed a selected 64-choice native permission budget (default 32); its grant scope did not change.</p><p>A <a href="/Rho/docs/records/simulated-project-episode">simulated-project episode</a> ran two rho-bio-eval capsule projects through Rho with Claude Code and changed what their screens showed: Studio&#39;s eight-view budget now renders the views on screen first, Overview opens with the latest answer, the Graph folds a message&#39;s versions of one file and its unrelated commands, Review (Annotations 0.5.2) offers questions and kept results as choices, a folder chosen in the system dialog stays in the local person&#39;s list across restarts, and a tab on this machine names its principal again, so the person&#39;s own edits read &quot;You&quot;. Row questions on an ordinary CSV still need an identity choice (a declared key column or a row position within one exact version); projects and conversations now have addresses, while other pages do not.</p><p>Its <a href="/Rho/docs/records/simulated-project-episode#second-pass">second pass</a> moved review onto the answer. The Overview leads with an answer board derived from the Graph: results by role, then method, run, inputs and report. Ask on a result or a selected passage continues the same conversation, and later questions stay with the answer they ask about. Use this answer or Needs changes (<code>conversation.decide</code>) is bound to the versions the message kept. Review is listed only while review records exist. The Console (Console 0.1.0) lists the Agent&#39;s and the person&#39;s commands, and runs, stops and reruns the person&#39;s own (local browser only). A message&#39;s commands read in the order they ran, each led by the Agent&#39;s own words on what it was for (Agent 0.4.23). Agent 0.4.19 keeps a command&#39;s whole text. Repeated reads no longer exhaust a message&#39;s capture budget before its results. Agent-declared choices are shown by the meaning layer pass below, without Agree/No.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#process-studio">process Studio</a> pass made Studio show how a conversation&#39;s work was done. Each conversation started in Rho has its own Studio, laid out from its record by role: data, script and a Commands view down one side, figures above tables and reports on the other, each file&#39;s view naming the kept version it shows. A chip names the part of the work in progress, and a timeline runs beside the Agent panel. A moment chosen there replays the views, commands, part and conversation together. Arranging saves the layout as <code>conversation-&lt;id&gt;</code>. The person&#39;s own workspace still opens nothing by itself. After the user judged that Studio ugly, with many components and messy contents, a stage under 1100 px shows <a href="/Rho/docs/records/simulated-project-episode#fewer-things-at-once">two places</a>, results above the work, each file has one line above it, and tab names keep their extension; the builder&#39;s reading only, and the graph acceptance fails at its figure card on <code>55d677c8</code> too.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#project-notes">project notes</a> pass lists the sessions under Studio in the sidebar, then the person&#39;s workspaces, and shares one set of notes (<code>project-notes.md</code>) beside every Studio layout. Rho asks each session it starts, in its Agent&#39;s instructions (Agent 0.4.20), to keep one section: a heading naming its task with its session marker, then Question, Data &amp; method, Key results with a figure and To do. That heading titles the session. In a live run Claude Code (DeepSeek V4.1 Flash) wrote its section unprompted by the message, and the title followed within seconds. The panel reads the notes formatted, ticks to-dos in place and edits them with a toolbar (Markdown 0.2.0, Documents 0.4.8); the person&#39;s edits save after a pause.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#meaning-layer">meaning layer</a> pass reads each section of the notes as a question, method, findings, figures, choices, file descriptions and to-dos, each with the files it links. Kept versions of the notes trace a statement to the message that wrote it and each file to the version kept then. The Graph shows Meaning + process by default, or either layer alone, with &quot;kept as&quot; and &quot;written in&quot; edges into the process. The answer board and Studio&#39;s file views say what each file holds. A choice shows what it is about and what was taken, with any other option the notes name under it, nested or in the same sentence, and what it gives; Use this instead drafts a message, and nothing waits on the person. The Agent followed the fixed subsections, linked its files and computed some alternatives, but described files at the end of its run, not as it wrote them, even when told to.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#descriptions-while-the-work-goes-on">descriptions</a> pass reads each file a running message writes: facts from its bytes within seconds, then one sentence from the conversation&#39;s model through the person&#39;s own Claude Code with no tools (Agent 0.4.22). Studio, the answer board and the Graph show the notes&#39; words first, then the sentence with its model, then the facts. In two live runs, results had facts within 6 s of being written and sentences within half a minute (10 s median in the first). <a href="/Rho/docs/records/simulated-project-episode#figures-cost-and-a-switch">Figures</a> go to the model as images when models.dev lists it as reading them, else as the code that made them. Each call is priced by Claude Code or from models.dev&#39;s price; the session popover shows the conversation&#39;s spend and a person-wide switch. In the ninth copy, 13 calls cost about $0.0086, and the first image sentence misnamed the plot type.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#quick-checks-choices-and-the-console">quick checks</a> from rho-bio-eval ran in Rho: bix-18 (Python) had 4 of 5 answers in range twice, the miss being a proportion against a range written as a percentage; bix-51 (R) had 7 of 7. The Choices and the Console were redrawn from what these runs showed.</p><p>The <a href="/Rho/docs/records/simulated-project-episode#the-notebook">Notebook</a> (Notebook 0.1.0) keeps a live R and a live Python session per project that the person shares with the Agent. Its page lists cells in the order they ran with who ran them and why, the code, output streamed as it is printed with messages and warnings in place, plots, and the session&#39;s variables; the person runs, edits, reruns and interrupts cells, and only they stop a session. A conversation&#39;s Studio shows the cells its Agent ran. In fresh quick checks the Agent ran its script in the session (bix-51 7 of 7 in 5 cells, bix-18 4 of 5 in 4 cells) rather than exploring cell by cell. The default Agent grant had reached its 64-method limit, so the limit is now 96 (<code>layeredGrantLimits.maxMethods</code>); a larger grant is still refused.</p><p>The Notebook is also a view of any Studio page (<a href="/Rho/docs/records/simulated-project-episode#exploring-a-finished-answer">episode</a>). The person makes empty workspaces of their own and adds the Notebook or project files to them. Explore in R or Python on a table or script, from Studio, the answer board or the file page, opens it on their workspace beside the Notebook: a table loads as a new value in their own cell, a script waits in the line to run. A Studio stage under 640 px shows its views one at a time. Pages cannot yet be renamed or removed.</p><p>Values of the live sessions have a view of their own (<a href="/Rho/docs/records/simulated-project-episode#looking-at-values">episode</a>). Notebook&#39;s <code>kernel.inspect</code> reads one value as its session describes it, without starting, waiting for or changing a session; each cell names the values it made, changed and removed. From the Notebook&#39;s variables or a cell&#39;s names the value opens beside the Notebook, or as a tab next to it when a split would leave either under 360 px: a table pages, sorts and gives each column&#39;s type and summary; a model its fit and coefficients; a list its parts, each opening in place with the code that reaches it, which Use in Notebook puts in the line. While a cell runs or after the value is gone, the last reading stays, dimmed, with the cell it was read after.</p><p>The four panes of interactive exploration, a script, its console, the variables and the plots, are made from these components (<a href="/Rho/docs/records/simulated-project-episode#script-console-variables-and-plots">episode</a>). ⌘/Ctrl+Enter or Run in an R or Python script runs the selection, or the statement the cursor is in, as the person&#39;s cell and moves on; a page without the Notebook gets one under the script. Variables and Plots are views of their own, in a column along the page&#39;s right side. R now draws on one device for the whole session, so a later cell draws over an earlier plot and a sourced script keeps each plot. No Agent ran cells in this layout.</p><p>The Notebook has <a href="/Rho/docs/records/simulated-project-episode#two-forms-of-the-notebook">two forms</a> of the same sessions, switched in its header: the notebook, and a console with one transcript of prompts and output, Enter that runs finished code and continues unfinished code, history, Esc and Clear. A Studio view saves its form with the page; one placed by running a script&#39;s line starts as a console.</p><p><a href="/Rho/docs/records/simulated-project-episode#toolbars">Toolbars</a> take one form whichever component puts a control in a view&#39;s header: quiet words and icons, Run in the accent, one kind of switch, and a control only while it can act (Documents 0.4.9: Save with unsaved edits, Review with a selection, Highlight changes while Agent or disk edits remain). The Activity row joined the Studio bar, so the code starts 72 px higher at 1440 × 900.</p><p><a href="/Rho/docs/records/agent-canvas-episode#the-person-s-own-hands-on-the-layout">By hand</a>, the person arranges Studio as the Agent does: × on the shown tab, a middle click, Delete or the tab&#39;s menu closes, with Undo; a group&#39;s + adds a view into it; the strip beside its tabs drags the whole group, also to a side of the page. Tabs narrow to icons, so a view&#39;s controls take a second row sooner. In a conversation&#39;s Studio a replay shows the work&#39;s views even when closed, and with all closed <a href="/Rho/docs/records/agent-canvas-episode#closing-every-view-of-a-conversation-s-studio">Lay out the work again</a> restores them. The live sessions&#39; views (Notebook, Variables, Plots, Data flow, Servers, a value) now come from the Kernel plugin&#39;s own <code>./ui</code> as registered components (Notebook 0.4.0), and the person&#39;s command line and records from the Console plugin&#39;s (Console 0.2.0); Rho keeps the layout, the page services it hands them, the Agent&#39;s commands and managed runs (<a href="/Rho/docs/reference/frontend">Frontend</a>). The views still use Rho&#39;s base classes and theme tokens, which no written contract names yet.</p><p><a href="/Rho/docs/records/simulated-project-episode#sources-that-follow-the-project">Sources follow the project</a>: Variables lists the live sessions&#39; values between Code and Results, each opening in Studio, and Workflows, Reports, References and Environment appear when the project holds such files. The Notebook&#39;s language switch is the small chip each cell carries, in its input as at the console.</p><p><a href="/Rho/docs/records/simulated-project-episode#data-flow-html-pages-and-object-dependent-cases">Data flow</a> joins code and values: each cell now names what it read and the project files and folders it named (Notebook 0.1.1), and a Data flow tab beside Variables draws the values a live session made as a graph from the files read to the results, each node titled with the meaning its <code># means:</code> comment gives (Notebook 0.5.5). An HTML file opens as its page (HTML 0.1.0) in a sandboxed frame with no network, with its project styles, scripts and images. In bix-46 (R, a DESeqResults object) both answers matched; the phylogenetics files of bix-58/60 (Python, ClipKIT run in the session) gave bix-60&#39;s 19 only for five of the ten trees and did not reproduce bix-58. The runs fixed an S4 value listed as changed by printing, scope and rerun errors in what a cell read, and unrecorded folders.</p><p><a href="/Rho/docs/records/remote-episode">Live sessions on a server</a>: R and Python can run in a folder on a server that ssh reaches as the person&#39;s own setup does (Notebook 0.2.0). A place names the ssh destination, the folder and setup lines; a check reports the system, R and Python there; each language&#39;s next session starts where the project marks it. A Servers view adds, checks and chooses places and lists a place&#39;s files, opening one as a copy under <code>remote/&lt;place&gt;/</code> with its size, time and digest; the Notebook, Variables and Data flow name where a session runs. On a disposable Linux server holding bix-46&#39;s data only, the analysis ran there (mexG −4.96, its plot shown here), a written file opened from Data flow, and a dropped network left the running cell unknown and ran nothing again. The episode fixed interrupt under dash, UTF-8 text from a login without a UTF-8 locale and Explore loading local paths on the server.</p><p><a href="/Rho/docs/records/remote-episode#servers-own-skills">Servers&#39; own skills</a> (Notebook 0.3.0): how a server is used is now the server&#39;s own skill, not Rho&#39;s code. A server the person manages with serverctl is reached through <code>serverctl exec</code>, which holds its login, and <code>kernel.servers</code> lists those servers with the skills serverctl binds to each; <code>kernel.server.skill</code> reads one. The Servers view lists them and reads one in place; the Agent&#39;s instructions say to follow them. On a disposable server whose R is only on a module path, with a skill saying so, the skill&#39;s line found R 4.2.2 where the person&#39;s check found none, and an Agent with Rho&#39;s tools only read the skill, named a place with its setup line and wrote where the skill says. Claude Code started in Rho loaded the person&#39;s own ssh-server-manager skill, ran its own shell and waits on the person&#39;s choice. The serverctl on this machine&#39;s path is older than its registry (&quot;schema 8 is newer than supported 5&quot;), and Rho shows that. A session left running after a drop, scheduler compute nodes and the real lab cluster were not exercised.</p><p><a href="/Rho/docs/records/remote-episode#a-study-on-a-lab-server">A study on a lab server</a>: the pa14-qs case in Rho-cases asks one paper&#39;s BixBench study in steps of an Agent with Rho&#39;s tools only, its data on a disposable server reached through serverctl with its own skill. Its first run spent 15 of 23 calls finding operations and reported the place&#39;s folder missing while a session ran in it. The protocol now describes the server operations, the first index summarizes each owner, a resolve continuation may add knownRefs, and the kernel looks for the folder after the setup lines. Steps 1 to 3 then found the server in five calls each and shared one live R session there (graded 4/5, 6/11, 0/7: analysis choices and, in step 3, stored results that the Agent showed do not come from the counts). The Overview, which said &quot;No work yet&quot;, now shows the Notebook&#39;s work.</p><p><a href="/Rho/docs/records/skills-episode">Project skills</a> (Skills 0.1.0): how work is done in a project is kept as its own skills, <code>SKILL.md</code> files in <code>.claude/skills/</code> that Claude Code loads and other Agents read through Rho. Each change keeps its author, reason, evidence and versions; undo is a change; an edit outside Rho is seen and kept before anything is written over it. The Skills page leads with a skill&#39;s newest change beside Undo, and the Overview lists the newest changes. In pa14-qs with the person&#39;s notes, every Agent listed the skills before its first cell, recorded the notes, and new Agents followed them (step 1 again 5/5). A rule an Agent widened while recording carried over too; the guidance now keeps the person&#39;s terms. Seed skills and records from failures are not built.</p><p><a href="/Rho/docs/records/timeline-events-episode">Timeline events</a>: a plugin names a read of who did what and when (Notebook 0.5.0 <code>kernel.events</code>, Console 0.3.0 <code>console.events</code>); the Graph, the Overview and a conversation&#39;s Studio place its events by principal: the person&#39;s cells and commands in a lane named You, an Agent&#39;s cells in its conversation&#39;s, others in Outside Rho. The Notebook keeps its name: in four runs of the person&#39;s &quot;在notebook 中演示一下ggplot2&quot;, Agents used the shared R session. The conversation that made a Quarto file began before the Notebook existed and could not be replayed. Agents now read that &quot;in the notebook&quot; means Rho&#39;s sessions, untested on old histories.</p><h2 id="existing-application" tabindex="-1">Existing application <a class="header-anchor" href="#existing-application" aria-label="Permalink to &quot;Existing application&quot;">​</a></h2><ul><li>Projects opens selected folders and manages finite source folders. Sources counts and browses Data, Code, Results &amp; figures and Notes in one bounded walk; Files exposes the project/source folders. Current-file previews remain current-file facts.</li><li>Studio shares one Documents buffer per logical document, with confirmed versions, own undo and concurrent-write detection. An Agent edit beside unsaved text is merged or sent through the Documents hook (<a href="/Rho/docs/records/documents-episode">record</a>). Tabs/splits/moves retain original layout intent and do not cancel tasks.</li><li>Agent supports Claude/Codex ACP, retained session identity, settings/model choices, native permission requests, cancellation/unknown outcomes, trash and Markdown conversation export. Reads/reconnect do not replay prompts (<a href="/Rho/docs/records/acp-multi-agent-episode">ACP</a>, <a href="/Rho/docs/records/agent-panel-episode">panel</a>).</li><li>Managed execution retains Core&#39;s original request identity, output, stop/repair facts and integrity checks. Native execution remains available without Core (<a href="/Rho/docs/records/native-tools-episode">boundary</a>). Completion, integrity, domain checks and model judgments are separate facts. Observing native tools grants no managed guarantee.</li><li>Project/method-scoped HTTP/SSE and MCP discovery expose selected owner capabilities. Local browser access uses same-origin loopback checks; narrower paired access keeps its project/method scope. Models cannot expand grants or create human decisions.</li><li>Independent UI extensions contribute views over selected capabilities; their previews use no project credentials or runtime (<a href="/Rho/docs/reference/plugin-authoring">authoring</a>).</li><li><code>rho-screen-check</code> opens a page at four widths in a real browser, reports what it measures beside a screenshot per width, and changes nothing on the page (<a href="/Rho/docs/records/screen-check-episode">record</a>). <a href="/Rho/docs/records/screen-check-episode#checkout-cleanup-on-2026-11-07">Checkout cleanup</a> removed eight superseded probes and five unused dsh bundles; the <a href="/Rho/docs/records/third-party-plugins-episode#retained-machine-records">sclet machine records</a> are now versioned and generated reports are ignored.</li></ul><p>Earlier observations retain their original scope in the <a href="/Rho/docs/records/home-project-episode">home/project</a>, <a href="/Rho/docs/records/agent-canvas-episode">sidebar/canvas</a>, <a href="/Rho/docs/records/graph-episode">Graph</a>, <a href="/Rho/docs/records/agent-page-episode">Agent page</a>, <a href="/Rho/docs/concepts/agent-activity">Agent activity</a> and <a href="/Rho/docs/records/backend-acceptance">backend acceptance</a> records.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Passes from the baseline (Rho 223/223, Plugins 104/104, an explicit unchanged Core binary) to Sources recorded up to Rho 273/274 and Plugins 151. Each first failure was an undeclared CSS variable, a stale count or limit in a check or a shell import, then fixed; each later miss was the MCP v2 test at its 30 s limit or a <code>.rho</code> cleanup race (<code>ENOTEMPTY</code>), passing alone. Their pages, ui:u2, person-files, agent-canvas, graph, agent-page, agent-ui, sources and review acceptances passed. The shell (editor focus at 390 px) and interaction (a <code>/^workspace/</code> sidebar row) acceptances failed before the toolbar pass and remain open; Git history keeps each count. Later passes (by-hand and plugin views, Rho 264/267, Plugins 161/161; timeline events, Rho 267/269, Plugins 163/163) had only those misses, and their browser acceptances passed. The <a href="/Rho/docs/records/review-evidence-episode">episode</a> records contract, browser and installed results; the fixed 0.5.1 candidate passed 230/230 (<a href="/Rho/docs/records/preview-0-5-1">preview</a>). No failure is omitted to make a pass. The 0.5.2 packaging pass recorded Rho 269/270 and Plugins 165/165, and Windows 11 x64 Rho 259/273 (13 skipped, MCP v2 cancelled) and Plugins 158/166 (8 skipped). The CI pass records Rho 275/277 and Plugins 165/166 on macOS in the <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/VERIFICATION.json" target="_blank" rel="noreferrer">ledger</a>. In <a href="/Rho/docs/records/ci-episode">CI</a> run 7 every job passed: 275/277 on macOS and Linux x64, 262/277 on Windows (15 skipped), and all four installations. The <a href="/Rho/docs/records/screen-check-episode">screen-check</a> pass ran 20 of 20 in a verification copy, and the installed tarball&#39;s <code>rho-screen-check</code> ran offline.</p><p>Automatic capture defaults: 8 MiB/snapshot, 64 snapshots and 32 MiB/turn, at most two workers/project, Files 512 MiB/1024 resources; export 512 MiB/128 files/4 MiB metadata, previews 200 rows/20 columns and 64 KiB text. Exhaustion preserves earlier evidence, output and uncertainty (<a href="/Rho/docs/reference/headless#retained-review-evidence">Headless</a>).</p><h2 id="scope-and-follow-up" tabindex="-1">Scope and follow-up <a class="header-anchor" href="#scope-and-follow-up" aria-label="Permalink to &quot;Scope and follow-up&quot;">​</a></h2><p>The product target is local WebUI on macOS arm64, Linux x64/arm64 and Windows x64, each installed from one tarball in CI. No cloud/account/team/billing, native shell, automatic runtime download or signed release is included; npm publication of a <code>v*</code> tag published <code>@rho-workspace/rho</code> 0.5.2 to 0.5.8 (<a href="/Rho/docs/reference/release#ci-and-npm-publication">0.5.8</a> on 2026-11-10 UTC). From 0.5.2 the person installs the Agent clients; Rho pins their ACP adapters. <a href="/Rho/docs/reference/release">Release</a> separates source, fixed composition, installation and future signed distribution. Offline evidence is not a workspace restore or executable analysis format. Existing archives keep owner fields and reject older formats that would lose state.</p><p>The withdrawn 2026-10-25 frontend guidance and the <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/design/2026-10-26/index.html" target="_blank" rel="noreferrer">2026-10-26 design commission</a> are not requirements or templates for these screens. Current work advances by running real episodes and reviewing their results (<a href="/Rho/docs/concepts/development">Development</a>, <a href="/Rho/docs/reference/frontend">Frontend</a>). No independent researcher trial or physical IME observation has yet established ease of use. The workspace&#39;s first load made a 404 from <code>agent.activity.capture</code>: the preview asked for a capture of an R script, and the example&#39;s paths carried the projects-folder prefix. The preview no longer asks for files capture refuses, and new installations get project-relative paths (<a href="/Rho/docs/records/screen-check-episode">record</a>).</p>',44)])])}const f=o(n,[["render",r]]);export{u as __pageData,f as default};
